# Let's try a smarter approach - use local search / simulated annealing
import random
from itertools import combinations

def check_girth_fast(adj, n, max_cycle_len=6):
    """Check if graph has any cycle of length <= max_cycle_len using BFS"""
    for start in range(n):
        visited = {start: (None, 0)}
        queue = [start]
        qi = 0
        while qi < len(queue):
            v = queue[qi]
            qi += 1
            dist = visited[v][1]
            if dist >= max_cycle_len:
                continue
            for w in adj[v]:
                if w not in visited:
                    visited[w] = (v, dist + 1)
                    queue.append(w)
                elif w != visited[v][0]:
                    cycle_len = dist + visited[w][1] + 1
                    if cycle_len <= max_cycle_len:
                        return False
    return True

def build_adj(edges, n):
    adj = {i: set() for i in range(n)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)
    return adj

def count_short_cycles(adj, n, max_len=6):
    """Count number of short cycles"""
    count = 0
    for start in range(n):
        visited = {start: (None, 0)}
        queue = [start]
        qi = 0
        while qi < len(queue):
            v = queue[qi]
            qi += 1
            dist = visited[v][1]
            if dist >= max_len:
                continue
            for w in adj[v]:
                if w not in visited:
                    visited[w] = (v, dist + 1)
                    queue.append(w)
                elif w != visited[v][0]:
                    cycle_len = dist + visited[w][1] + 1
                    if cycle_len <= max_len:
                        count += 1
    return count // 2  # Each cycle counted twice

def try_local_search(n, min_deg=3, max_deg=4, target_girth=7, iterations=100000):
    random.seed(123)

    best_edges = None
    best_violations = float('inf')

    for attempt in range(50):
        # Start with a random graph that satisfies degree constraints
        edges = set()
        degrees = [0] * n

        # First, create a random 3-regular-ish graph
        # Use configuration model approach
        stubs = []
        for i in range(n):
            stubs.extend([i] * 3)
        random.shuffle(stubs)

        # Pair up stubs
        for i in range(0, len(stubs), 2):
            u, v = stubs[i], stubs[i+1]
            if u != v:
                edges.add((min(u,v), max(u,v)))

        # Remove self-loops and duplicate edges
        valid_edges = set()
        for u, v in edges:
            if u != v:
                valid_edges.add((min(u,v), max(u,v)))
        edges = valid_edges

        # Recalculate degrees
        degrees = [0] * n
        for u, v in edges:
            degrees[u] += 1
            degrees[v] += 1

        # Now do local search
        adj = build_adj(edges, n)

        for it in range(iterations):
            violations = count_short_cycles(adj, n, target_girth - 1)
            deg_violations = sum(1 for d in degrees if d < min_deg or d > max_deg)
            total_violations = violations + deg_violations * 10

            if total_violations == 0:
                print(f"Found solution on attempt {attempt}, iteration {it}!")
                return list(edges)

            if total_violations < best_violations:
                best_violations = total_violations
                best_edges = list(edges)

            # Try a random edge swap
            if random.random() < 0.5:
                # Remove a random edge and add a new one
                if edges:
                    edge_to_remove = random.choice(list(edges))
                    edges.remove(edge_to_remove)
                    u, v = edge_to_remove
                    degrees[u] -= 1
                    degrees[v] -= 1

                    # Try to add a new edge
                    for _ in range(100):
                        new_u = random.randint(0, n-1)
                        new_v = random.randint(0, n-1)
                        if new_u >= new_v:
                            continue
                        if (new_u, new_v) in edges:
                            continue
                        if degrees[new_u] >= max_deg or degrees[new_v] >= max_deg:
                            continue

                        test_edges = edges | {(new_u, new_v)}
                        test_adj = build_adj(test_edges, n)
                        if check_girth_fast(test_adj, n, target_girth - 1):
                            edges.add((new_u, new_v))
                            degrees[new_u] += 1
                            degrees[new_v] += 1
                            adj = test_adj
                            break
                    else:
                        # Couldn't add edge, put back the removed one
                        edges.add(edge_to_remove)
                        degrees[u] += 1
                        degrees[v] += 1
                        adj = build_adj(edges, n)
            else:
                # Try edge swap: remove (a,b), add (a,c) or (b,c)
                if edges:
                    edge_to_remove = random.choice(list(edges))
                    a, b = edge_to_remove

                    # Try to reconnect a or b to a new vertex
                    for endpoint in [a, b]:
                        for _ in range(50):
                            c = random.randint(0, n-1)
                            if c == a or c == b:
                                continue
                            new_edge = (min(endpoint, c), max(endpoint, c))
                            if new_edge in edges:
                                continue
                            if degrees[c] >= max_deg:
                                continue

                            test_edges = (edges - {edge_to_remove}) | {new_edge}
                            test_adj = build_adj(test_edges, n)
                            if check_girth_fast(test_adj, n, target_girth - 1):
                                edges = test_edges
                                degrees[a] -= 1
                                degrees[b] -= 1
                                degrees[c] += 1
                                degrees[endpoint] += 1  # net zero for endpoint
                                adj = test_adj
                                break

        if attempt % 10 == 0:
            print(f"Attempt {attempt}: best violations = {best_violations}")

    return best_edges

result = try_local_search(26)
print(f"Result has {len(result)} edges")
if result:
    deg = [0]*26
    for u,v in result:
        deg[u] += 1
        deg[v] += 1
    print(f"Degree distribution: {sorted(deg)}")
    print(f"Min degree: {min(deg)}, Max degree: {max(deg)}")
    adj = build_adj(result, 26)
    ok = check_girth_fast(adj, 26, 6)
    print(f"Girth check: {'PASS' if ok else 'FAIL'}")

# Let's try a smarter approach - incremental SAT solving
# First solve without 5/6 cycles, then add them incrementally

from pysat.solvers import Glucose3
from itertools import combinations
import random

n = 26
min_deg = 3
max_deg = 4

# Create edge variables
edge_var = {}
var_count = 0
for i in range(n):
    for j in range(i+1, n):
        var_count += 1
        edge_var[(i, j)] = var_count

def build_adj_from_model(model, n):
    adj = {i: set() for i in range(n)}
    for (i, j), var in edge_var.items():
        if var in model:
            adj[i].add(j)
            adj[j].add(i)
    return adj

def find_short_cycles(adj, n, max_len=6):
    """Find all cycles of length <= max_len"""
    cycles = []
    for start in range(n):
        visited = {start: (None, 0)}
        queue = [start]
        qi = 0
        while qi < len(queue):
            v = queue[qi]
            qi += 1
            dist = visited[v][1]
            if dist >= max_len:
                continue
            for w in adj[v]:
                if w not in visited:
                    visited[w] = (v, dist + 1)
                    queue.append(w)
                elif w != visited[v][0]:
                    cycle_len = dist + visited[w][1] + 1
                    if cycle_len <= max_len:
                        # Reconstruct cycle
                        cycles.append(cycle_len)
    return cycles

def find_specific_cycle(adj, n, max_len=6):
    """Find a specific cycle and return its edges"""
    for start in range(n):
        parent = {start: None}
        dist = {start: 0}
        queue = [start]
        qi = 0
        while qi < len(queue):
            v = queue[qi]
            qi += 1
            for w in adj[v]:
                if w not in dist:
                    dist[w] = dist[v] + 1
                    parent[w] = v
                    queue.append(w)
                elif w != parent[v] and dist[v] + dist[w] + 1 <= max_len:
                    # Found cycle, reconstruct
                    cycle_edges = set()
                    # Path from start to v
                    path_v = []
                    cur = v
                    while cur != start:
                        path_v.append((min(cur, parent[cur]), max(cur, parent[cur])))
                        cur = parent[cur]
                    # Path from start to w
                    path_w = []
                    cur = w
                    while cur != start:
                        path_w.append((min(cur, parent[cur]), max(cur, parent[cur])))
                        cur = parent[cur]
                    # Edge (v, w)
                    cycle_edges.add((min(v,w), max(v,w)))
                    cycle_edges.update(path_v)
                    cycle_edges.update(path_w)
                    return cycle_edges
    return None

# Build base clauses (degree + no triangles + no 4-cycles)
clauses = []

for v in range(n):
    incident = []
    for u in range(n):
        if u < v:
            incident.append(edge_var[(u, v)])
        elif u > v:
            incident.append(edge_var[(v, u)])

    for subset in combinations(incident, 5):
        clauses.append([-x for x in subset])

    for subset in combinations(incident, len(incident) - 3 + 1):
        clauses.append([x for x in subset])

for a, b, c in combinations(range(n), 3):
    e1 = edge_var[(min(a,b), max(a,b))]
    e2 = edge_var[(min(b,c), max(b,c))]
    e3 = edge_var[(min(a,c), max(a,c))]
    clauses.append([-e1, -e2, -e3])

for a, b, c, d in combinations(range(n), 4):
    cycles = [
        [(a,b), (b,c), (c,d), (d,a)],
        [(a,b), (b,d), (d,c), (c,a)],
        [(a,c), (c,b), (b,d), (d,a)]
    ]
    for cycle in cycles:
        e_vars = [edge_var[(min(u,v), max(u,v))] for u, v in cycle]
        clauses.append([-e for e in e_vars])

print(f"Base clauses: {len(clauses)}")

# Incremental solving
solver = Glucose3()
for clause in clauses:
    solver.add_clause(clause)

max_iterations = 500
for iteration in range(max_iterations):
    if solver.solve():
        model = solver.get_model()
        adj = build_adj_from_model(model, n)

        # Check for 5-cycles and 6-cycles
        cycle_edges = find_specific_cycle(adj, n, 6)
        if cycle_edges is None:
            # Found valid solution!
            edge_list = []
            for (i, j), var in edge_var.items():
                if var in model:
                    edge_list.append((i, j))

            deg = [0]*26
            for u,v in edge_list:
                deg[u] += 1
                deg[v] += 1

            print(f"Found solution after {iteration} iterations!")
            print(f"Edges: {len(edge_list)}")
            print(f"Degree distribution: {sorted(deg)}")
            print(f"Min: {min(deg)}, Max: {max(deg)}")

            # Final verification
            min_cycle = float('inf')
            for start in range(n):
                visited = {start: (None, 0)}
                queue = [start]
                qi = 0
                while qi < len(queue):
                    v = queue[qi]
                    qi += 1
                    d = visited[v][1]
                    for w in adj[v]:
                        if w not in visited:
                            visited[w] = (v, d + 1)
                            queue.append(w)
                        elif w != visited[v][0]:
                            cl = d + visited[w][1] + 1
                            min_cycle = min(min_cycle, cl)

            print(f"Girth: {min_cycle}")
            if min_cycle >= 7:
                print("VALID!")
                print(edge_list)
            break
        else:
            # Add clause to break this cycle
            cycle_clause = []
            for u, v in cycle_edges:
                cycle_clause.append(-edge_var[(u, v)])
            solver.add_clause(cycle_clause)

            if iteration % 50 == 0:
                print(f"Iteration {iteration}: found cycle, added blocking clause")
    else:
        print(f"UNSAT after {iteration} iterations")
        break

