import random
from itertools import combinations

def check_girth_bfs(adj, n, max_cycle=6):
    """Check girth using BFS from each vertex"""
    for start in range(n):
        visited = {start: (None, 0)}
        queue = [start]
        qi = 0
        while qi < len(queue):
            v = queue[qi]
            qi += 1
            dist = visited[v][1]
            if dist >= max_cycle:
                continue
            for w in adj[v]:
                if w not in visited:
                    visited[w] = (v, dist + 1)
                    queue.append(w)
                elif w != visited[v][0]:
                    cycle_len = dist + visited[w][1] + 1
                    if cycle_len <= max_cycle:
                        return False, cycle_len
    return True, None

def try_construction_v2(n, min_deg=3, max_deg=4, target_girth=7, num_attempts=5000):
    """Try random construction with better heuristics"""
    random.seed(456)

    best_edges = None
    best_min_deg = 0

    for attempt in range(num_attempts):
        edges = set()
        degrees = [0] * n

        # Build graph by adding edges one at a time
        # Prioritize vertices with low degree
        all_possible = [(i, j) for i in range(n) for j in range(i+1, n)]

        # Sort by sum of degrees (prefer connecting low-degree vertices)
        # But we need to do this dynamically

        for _ in range(n * max_deg):  # Maximum possible edges
            # Find vertex with lowest degree
            min_deg_v = min(range(n), key=lambda v: degrees[v])
            if degrees[min_deg_v] >= max_deg:
                break

            # Try to connect to a vertex that doesn't create short cycles
            candidates = []
            for v in range(n):
                if v == min_deg_v:
                    continue
                if degrees[v] >= max_deg:
                    continue
                u, w = min(min_deg_v, v), max(min_deg_v, v)
                if (u, w) in edges:
                    continue

                # Check if adding this edge creates a short cycle
                test_edges = edges | {(u, w)}
                adj = {i: set() for i in range(n)}
                for x, y in test_edges:
                    adj[x].add(y)
                    adj[y].add(x)

                ok, _ = check_girth_bfs(adj, n, target_girth - 1)
                if ok:
                    candidates.append(v)

            if not candidates:
                break

            # Choose randomly among valid candidates
            v = random.choice(candidates)
            u, w = min(min_deg_v, v), max(min_deg_v, v)
            edges.add((u, w))
            degrees[min_deg_v] += 1
            degrees[v] += 1

        min_d = min(degrees)
        if min_d > best_min_deg:
            best_min_deg = min_d
            best_edges = list(edges)
            print(f"Attempt {attempt}: min degree = {min_d}, edges = {len(edges)}")

        if min_d >= min_deg:
            # Verify girth
            adj = {i: set() for i in range(n)}
            for u, v in edges:
                adj[u].add(v)
                adj[v].add(u)
            ok, cl = check_girth_bfs(adj, n, target_girth - 1)
            if ok:
                print(f"FOUND SOLUTION on attempt {attempt}!")
                return list(edges)

    print(f"Best min degree achieved: {best_min_deg}")
    return best_edges

